import json

with open("/app/dialogue.json", "r") as f:
    graph = json.load(f)

nodes = {node['id']: node for node in graph['nodes']}
edges = graph['edges']

# Check existence of targets
missing_targets = set()
for edge in edges:
    if edge['to'] not in nodes and edge['to'] != "End":
        missing_targets.add(edge['to'])

if missing_targets:
    print(f"Missing targets: {missing_targets}")
else:
    print("All targets exist (or are 'End').")

# Reachability
reachable = set()
first_node = graph['nodes'][0]['id']
queue = [first_node]
reachable.add(first_node)

while queue:
    current = queue.pop(0)
    for edge in edges:
        if edge['from'] == current:
            if edge['to'] not in reachable:
                reachable.add(edge['to'])
                if edge['to'] in nodes:
                    queue.append(edge['to'])

unreachable = set(nodes.keys()) - reachable
if unreachable:
    print(f"Unreachable nodes: {unreachable}")
else:
    print("All nodes are reachable.")

# Check if End is reachable
if "End" in reachable:
    print("'End' is reachable.")
elif "End" in {edge['to'] for edge in edges}:
    print("'End' is targeted but not reached in BFS (should be reached if targeted).")

