import json
import re

def parse_script(text: str):
    # Use a more robust way to split blocks
    # Blocks start with [ID] at the beginning of a line
    raw_blocks = re.split(r'^\[(.*?)\]', text, flags=re.MULTILINE)

    # re.split with capturing group returns [prefix, id1, content1, id2, content2, ...]
    # prefix should be empty if the file starts with [ID]

    nodes = []
    edges = []
    node_ids = set()

    for i in range(1, len(raw_blocks), 2):
        node_id = raw_blocks[i].strip()
        content = raw_blocks[i+1].strip()

        node_ids.add(node_id)

        # Check if it's a choice block
        choice_matches = re.findall(r'^\d+\.\s*(.*?)\s*->\s*(\w+)', content, re.MULTILINE)

        if choice_matches:
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            })
            for choice_text, target in choice_matches:
                edges.append({
                    "from": node_id,
                    "to": target.strip(),
                    "text": choice_text.strip()
                })
        else:
            # Line node
            line_match = re.search(r'^(.*?):\s*(.*?)\s*->\s*(\w+)', content, re.DOTALL)
            if line_match:
                speaker = line_match.group(1).strip()
                text_content = line_match.group(2).strip()
                # Clean up newlines in text
                text_content = re.sub(r'\s+', ' ', text_content)
                target = line_match.group(3).strip()

                nodes.append({
                    "id": node_id,
                    "text": text_content,
                    "speaker": speaker,
                    "type": "line"
                })
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })
            else:
                # If no line match, maybe it's a terminal node or narrator line without target
                # But constraints suggest every node has a target except the last
                nodes.append({
                    "id": node_id,
                    "text": content,
                    "speaker": "",
                    "type": "line"
                })

    all_targets = {edge['to'] for edge in edges}
    if "End" not in node_ids and "End" in all_targets:
        nodes.append({
            "id": "End",
            "text": "",
            "speaker": "",
            "type": "line"
        })
        node_ids.add("End")

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot = ["digraph G {"]
    for node in graph['nodes']:
        label = node['id']
        if node['type'] == 'line' and node['text']:
            label = f"{node['speaker']}: {node['text']}" if node['speaker'] else node['text']
        elif node['type'] == 'choice':
            label = f"{node['id']} (Choice)"

        clean_label = label.replace('"', '\\"')
        shape = "box" if node['type'] == 'line' else "diamond"
        dot.append(f'  "{node["id"]}" [label="{clean_label}", shape={shape}];')

    for edge in graph['edges']:
        label = edge['text'].replace('"', '\\"')
        dot.append(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    try:
        with open("/app/script.txt", "r") as f:
            script_content = f.read()

        graph = parse_script(script_content)

        with open("/app/dialogue.json", "w") as f:
            json.dump(graph, f, indent=2)

        dot_content = generate_dot(graph)
        with open("/app/dialogue.dot", "w") as f:
            f.write(dot_content)
    except Exception as e:
        import traceback
        traceback.print_exc()

