            })
            for choice_text, target in choice_lines:
                edges.append({
                    "from": node_id,
                    "to": target.strip(),
                    "text": choice_text.strip()
                })
        else:
            # Line pattern: Speaker: Text -> Target
            # Using a more robust line parser
            lines = content.split('\n')
            found_line = False
            for line in lines:
                if ':' in line and '->' in line:
                    parts = line.split('->')
                    target = parts[-1].strip()
                    main_part = '->'.join(parts[:-1]).strip()
                    speaker_parts = main_part.split(':', 1)
                    if len(speaker_parts) == 2:
                        speaker = speaker_parts[0].strip()
                        txt = speaker_parts[1].strip()
                        nodes.append({
                            "id": node_id,
                            "text": txt,
                            "speaker": speaker,
                            "type": "line"
                        })
                        edges.append({
                            "from": node_id,
                            "to": target,
                            "text": ""
                        })
                        found_line = True
                        break
            if not found_line:
                nodes.append({
                    "id": node_id,
                    "text": content,
                    "speaker": "",
                    "type": "line"
